import json
import pandas as pd

def clean(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return ''
    return str(v).strip()

records = {}

def add(email, phone, status):
    e = clean(email)
    if not e:
        return
    cur = records.setdefault(e, {'email': e, 'phone': '', 'status': ''})
    if not cur['phone'] and clean(phone):
        cur['phone'] = clean(phone)
    if not cur['status'] and clean(status):
        cur['status'] = clean(status)

users = pd.read_csv('/workspace/users.csv', dtype=str, keep_default_na=False)
for _, r in users.iterrows():
    add(r.get('email', ''), r.get('phone', ''), r.get('status', ''))

with open('/workspace/records.jsonl') as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        r = json.loads(line)
        other = r.get('other_info') or {}
        add(r.get('email'), r.get('phone') or other.get('phone'), r.get('status'))

with open('/workspace/profiles.json') as f:
    profiles = json.load(f)
if isinstance(profiles, dict):
    items = [(k, v) for k, v in profiles.items()]
else:
    items = [(None, v) for v in profiles]
for key, r in items:
    other = r.get('other_info') or {}
    add(r.get('email') or key, r.get('phone') or other.get('phone'), r.get('status'))

out = pd.DataFrame(list(records.values()), columns=['email', 'phone', 'status'])
out.to_csv('/workspace/merged_records.csv', index=False)
print(len(out), 'rows written')
EOF
